const staticData = $getWorkflowStaticData('global');
staticData.alertCache = staticData.alertCache || {};
const item = $input.item.json;
const now = Date.now();
const throttleWindowMs = 15 * 60 * 1000;
// Expire old cache entries to avoid unlimited growth.
for (const [key, ts] of Object.entries(staticData.alertCache)) {
  if (now - ts >= throttleWindowMs) delete staticData.alertCache[key];
}
let severity = 'P3_MINOR';
if (item.impactedUsers > 100 && item.env === 'production') severity = 'P1_CRITICAL';
else if (item.env === 'production' || item.impactedUsers > 0) severity = 'P2_MAJOR';
const throttleKey = `${item.service}:${item.errorSignature}`;
const lastAlertTime = staticData.alertCache[throttleKey] || 0;
const isThrottled = now - lastAlertTime < throttleWindowMs;
if (!isThrottled) staticData.alertCache[throttleKey] = now;
return {json:{...item,severity,isThrottled,shouldAlert:!isThrottled,throttleKey,evaluatedAt:new Date().toISOString()}};

const item = $input.item.json;
const dispatchPayload = {
 channel:'#critical-incidents',
 text:`P1 CRITICAL INCIDENT: ${item.service} | ${item.incidentId} | ${item.evaluatedAt}`,
 blocks:[
  {type:'header',text:{type:'plain_text',text:`P1 CRITICAL: ${item.service.toUpperCase()}`,emoji:true}},
  {type:'section',fields:[
   {type:'mrkdwn',text:`*Incident ID:*\n\`${item.incidentId}\``},
   {type:'mrkdwn',text:`*Environment:*\n\`${item.env.toUpperCase()}\``},
   {type:'mrkdwn',text:`*Impacted Users:*\n*${item.impactedUsers}*`},
   {type:'mrkdwn',text:`*Signature:*\n\`${item.errorSignature}\``}
  ]},
  {type:'section',text:{type:'mrkdwn',text:`*Diagnostic Message:*\n>${item.message}`}},
  {type:'context',elements:[{type:'mrkdwn',text:`Evaluated: ${item.evaluatedAt}`}]}
 ]
};
return {json:{incidentId:item.incidentId,severity:item.severity,dispatchPayload}};

