const data=$getWorkflowStaticData('global');
data.digestQueue=data.digestQueue || [];
const record={incidentId:$json.incidentId,service:$json.service,message:$json.message,severity:$json.severity,queuedAt:new Date().toISOString()};
data.digestQueue.push(record);
return {json:{...record,channel:'digest_queue',digestStatus:'QUEUED',queueLength:data.digestQueue.length}};

const resp=$input.item.json;
const statusCode=resp.statusCode ?? null;
const body=resp.body ?? resp;
const queued=resp.digestStatus==='QUEUED';
const delivered=!queued && statusCode>=200 && statusCode<300 && body?.ok!==false;
return {json:{event:queued?'NOTIFICATION_QUEUED':'NOTIFICATION_DISPATCH_ATTEMPTED',channel:resp.channel || body?.channel || (queued?'digest_queue':'mock_slack'),deliveryStatus:queued?'QUEUED':(delivered?'DELIVERED':'FAILED'),httpStatus:statusCode,error:resp.error?.message || (delivered||queued?null:'Mock endpoint did not confirm delivery'),timestamp:new Date().toISOString()}};
